nt(f\"Government: {govt_cv}\")\nprint(f\"Public: {public_cv}\")\n\n# Absolute difference\nabs_diff = abs(govt_cv - public_cv)\nprint(f\"\\nAbsolute difference: {abs_diff}\")\nprint(f\"Rounded to nearest thousandth: {round(abs_diff, 3)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
